UPDATE products AS p
SET price = c.new_price
FROM price_changes AS c
WHERE c.product_id = p.id;
SELECT id, name, price FROM products ORDER BY id;

practice.solution:
UPDATE products AS p
SET price = c.new_price
FROM price_changes AS c
WHERE c.product_id = p.id
    AND c.new_price < p.price;
SELECT name, price FROM products ORDER BY id;
